import { useEffect, useState } from 'react'
import { connect } from 'react-redux'
import { notification, Row, Button, Icon, Input } from 'antd'
import ErrorBoundary from '../../../components/ErrorBoundary'
import TableWrapper from '../Provider/pagination.style'
import LayoutContent from '../../../components/utility/layoutContent'
import ServiceCenterActions from '../../redux/serviceCenter/actions'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import { serviceListColumns } from './serviceListColumns'
import PermissionChecker from '../../../components/permissionChecker'
import AddServiceCenterModal from './addServiceCenter'
import Highlighter from 'react-highlight-words'

const { getServiceCenterList } = ServiceCenterActions

function ServiceCenterComponent (props) {
  const {
    permissions,
    serviceCenterList,
    serviceCenterListMessage,
    serviceCenterListError,
    serviceCenterListLoading,
    getServiceCenterList
  } = props

  const [isShowAddServiceCenter, setIsShowAddServiceCenter] = useState(false)
  const [searchObject, setSearchData] = useState({ searchText: '', searchedColumn: '' })

  useEffect(() => {
    getServiceCenterList()
  }, [getServiceCenterList])

  useEffect(() => {
    if (serviceCenterListError) {
      notification.error({
        message: serviceCenterListMessage
      })
    }
  }, [serviceCenterListError, serviceCenterListMessage])

  const openAddSeviceCenterModal = () => {
    setIsShowAddServiceCenter(true)
  }

  const closeAddSeviceCenterModal = () => {
    setIsShowAddServiceCenter(false)
  }

  const totalRecords = serviceCenterList ? serviceCenterList.length : 0

  const handleSearch = (selectedKeys, confirm, dataIndex) => {
    confirm()
    setSearchData({
      searchText: selectedKeys[0],
      searchedColumn: dataIndex
    })
  }

  const handleReset = clearFilters => {
    clearFilters()
    setSearchData({
      searchText: ''
    })
  }

  let searchInput
  const getColumnSearchProps = dataIndex => ({
    filterDropdown: ({ setSelectedKeys, selectedKeys, confirm, clearFilters }) => (
      <div style={{ padding: 8 }}>
        <Input
          ref={node => {
            searchInput = node
          }}
          placeholder={`Search ${dataIndex}`}
          value={selectedKeys[0]}
          onChange={e => setSelectedKeys(e.target.value ? [e.target.value] : [])}
          onPressEnter={() => handleSearch(selectedKeys, confirm, dataIndex)}
          style={{ width: 188, marginBottom: 8, display: 'block' }}
        />
        <Button
          type='primary'
          onClick={() => handleSearch(selectedKeys, confirm, dataIndex)}
          icon='search'
          size='small'
          style={{ width: 90, marginRight: 8 }}
        >
          Search
        </Button>
        <Button onClick={() => handleReset(clearFilters)} size='small' style={{ width: 90 }}>
          Reset
        </Button>
      </div>
    ),
    filterIcon: filtered => (
      <Icon type='search' style={{ color: filtered ? '#1890ff' : undefined }} />
    ),
    onFilter: (value, record) =>
      record[dataIndex]
        .toString()
        .toLowerCase()
        .includes(value.toLowerCase()),
    onFilterDropdownVisibleChange: visible => {
      if (visible) {
        setTimeout(() => searchInput.select())
      }
    },
    render: text =>
      searchObject.searchedColumn === dataIndex
        ? <Highlighter
            highlightStyle={{ backgroundColor: '#ffc069', padding: 0 }}
            searchWords={[searchObject.searchText]}
            autoEscape
            textToHighlight={text.toString()}
          />
        : (
            text
          )
  })

  return (
    <ErrorBoundary>
      <LayoutContentWrapper className='referral-table' style={{ color: '#788195' }}>
        <AddServiceCenterModal
          isOpen={isShowAddServiceCenter}
          onClosePopupForm={closeAddSeviceCenterModal}
        />
        <LayoutContent>
          <Row style={{ marginBottom: '10px' }}>
            <div>
              <h3 style={{ float: 'left', color: '#788195' }}>Service center List</h3>
              <div>
                <p
                  style={{
                    float: 'left',
                    color: '#4482FF',
                    marginLeft: '10px',
                    marginTop: '3px'
                  }}
                >
                  {totalRecords}
                </p>
              </div>
            </div>
            <div style={{ float: 'right', display: 'flex' }}>
              <PermissionChecker permissionSetter='ops.create_service_center' permissionGetter={permissions}>
                <Button onClick={openAddSeviceCenterModal}>
                  <Icon type='plus' theme='outlined' /> &nbsp; Add Service Center
                </Button>
              </PermissionChecker>
            </div>
          </Row>
          <TableWrapper
            columns={serviceListColumns(props, getColumnSearchProps)}
            bordered
            rowKey={record => record.InternalID}
            dataSource={serviceCenterList}
            loading={serviceCenterListLoading}
            className='isoSearchableTable'
            scroll={{ x: true }}
          />
        </LayoutContent>
      </LayoutContentWrapper>
    </ErrorBoundary>
  )
}

export default connect((state) => ({
  serviceCenterList: state.ServiceCenter.serviceCenterList,
  serviceCenterListLoading: state.Loading.GET_SERVICE_CENTER_LIST,
  serviceCenterListError: state.Error.GET_SERVICE_CENTER_LIST,
  serviceCenterListMessage: state.ServiceCenter.serviceCenterListMessage,

  profileData: state.Auth.profile

}), ({
  getServiceCenterList
}))(ServiceCenterComponent)
