import { Icon } from 'antd'
import moment from 'moment'
export const serviceListColumns = (props, getColumnSearchProps) => [
  {
    key: 'id',
    dataIndex: 'id',
    title: 'View',
    render: (_, data) => <Icon className='view-icon' type='eye' onClick={() => props.history.push(`/service-center/${data.code}`)} />
  },
  {
    key: 'name',
    dataIndex: 'name',
    title: 'Service center name',
    ...getColumnSearchProps('name')
  },
  {
    key: 'country',
    dataIndex: 'country',
    title: 'Country',
    ...getColumnSearchProps('country')
  },
  {
    key: 'created_at',
    dataIndex: 'created_at',
    title: 'Created At',
    render: (text) => text ? moment(text).format('DD/MM/YYYY') : ''
  },
  {
    key: 'created_by',
    dataIndex: 'created_by',
    title: 'Created By'
  },
  {
    key: 'updated_at',
    dataIndex: 'updated_at',
    title: 'Last modified',
    render: (text) => text ? moment(text).format('DD/MM/YYYY') : ''
  },
  {
    key: 'updated_by',
    dataIndex: 'updated_by',
    title: 'Last modified By'
  },
  {
    key: 'is_active',
    dataIndex: 'is_active',
    title: 'Status',
    render: (text) => text ? 'Active' : 'Inactive'
  }

]
